        <label htmlFor="aviso-titulo">Título</label>
        <input
          id="aviso-titulo"
          style={fieldStyle}
          maxLength={150}
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Ex: Feriado na sexta-feira"
        />

        <label htmlFor="aviso-mensagem">Mensagem</label>
        <textarea
          id="aviso-mensagem"
          style={{ ...fieldStyle, minHeight: '120px' }}
