    ResetPasswordRequest,
    TokenResponse,
    UserLoginRequest,
    UserRegisterRequest,
    UserResponse,
    UserUpdateRequest,
    VerifyEmailRequest,
)
from src.backend.modules.auth.service import (
    AuthService,
    InvalidRefreshToken,
    IssuedTokens,
    SamePassword,
    WrongCurrentPassword,
)

router = APIRouter()

REFRESH_COOKIE = "refresh_token"
# O cookie só vai para as rotas de /api/auth (refresh e logout), não para o resto da API.
